// ... existing tests ...

test('step: bounce off brick top face', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // top-left brick
  brick.alive = true;
  // Position ball just above the brick, moving down
  state.ball = { x: brick.x + BRICK_W / 2, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: 200 };
  step(state, 0.01); // should hit the brick
  assert.ok(state.ball.vy < 0, 'should bounce up');
  assert.ok(state.ball.y <= brick.y - BALL_R, 'should be pushed out of the brick');
});

test('step: bounce off brick bottom face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Position ball just below the brick, moving up
  state.ball = { x: brick.x + BRICK_W / 2, y: brick.y + BRICK_H + BALL_R + 1, r: BALL_R, vx: 0, vy: -200 };
  step(state, 0.01);
  assert.ok(state.ball.vy > 0, 'should bounce down');
  assert.ok(state.ball.y >= brick.y + BRICK_H + BALL_R, 'should be pushed out of the brick');
});

test('step: bounce off brick left face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Position ball to the left, moving right
  state.ball = { x: brick.x - BALL_R - 1, y: brick.y + BRICK_H / 2, r: BALL_R, vx: 200, vy: 0 };
  step(state, 0.01);
  assert.ok(state.ball.vx < 0, 'should bounce left');
  assert.ok(state.ball.x <= brick.x - BALL_R, 'should be pushed out');
});

test('step: bounce off brick right face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Position ball to the right, moving left
  state.ball = { x: brick.x + BRICK_W + BALL_R + 1, y: brick.y + BRICK_H / 2, r: BALL_R, vx: -200, vy: 0 };
  step(state, 0.01);
  assert.ok(state.ball.vx > 0, 'should bounce right');
  assert.ok(state.ball.x >= brick.x + BRICK_W + BALL_R, 'should be pushed out');
});

test('step: bounce off brick corner', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Position ball at top-left corner, moving down-right
  state.ball = { x: brick.x - BALL_R - 1, y: brick.y - BALL_R - 1, r: BALL_R, vx: 200, vy: 200 };
  step(state, 0.01);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'should bounce diagonally up-left');
});

test('step: prevent double bounce on seams', () => {
  const state = createState(1);
  // Create two adjacent bricks
  const brick1 = { x: 100, y: 100, w: BRICK_W, h: BRICK_H, alive: true };
  const brick2 = { x: 100 + BRICK_W, y: 100, w: BRICK_W, h: BRICK_H, alive: true };
  state.bricks = [brick1, brick2];
  // Position ball overlapping the seam, moving up
  state.ball = { x: 100 + BRICK_W, y: 100 + BRICK_H + BALL_R + 1, r: BALL_R, vx: 0, vy: -200 };
  step(state, 0.01);
  assert.ok(state.ball.vy > 0, 'should bounce down once, not twice');
});

test('step: prevent tunneling', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Very fast ball that would jump over the brick in one step
  // Brick is at y=48, h=20. Top=48, Bottom=68.
  // Ball is at y=40, r=7. Bottom = 47.
  // Ball moves to y = 40 + 100 * 0.1 = 50. Wait, that's not tunneling.
  // Ball moves to y = 40 + 1000 * 0.1 = 140. It jumped from 40 to 140.
  state.ball = { x: brick.x + BRICK_W / 2, y: brick.y - BALL_R - 10, r: BALL_R, vx: 0, vy: 2000 };
  step(state, 0.05); // jump of 100px
  assert.ok(state.ball.vy < 0, 'should have detected collision via sweep and bounced');
});

