// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle, and bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const oldX = ball.x;
  const oldY = ball.y;

  // To prevent tunneling and ensure accurate bounces, we subdivide the step.
  const stepSize = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy) * dt;
  const maxStep = ball.r; 
  const subSteps = Math.max(1, Math.ceil(stepSize / maxStep));
  const subDt = dt / subSteps;

  let currentX = oldX;
  let currentY = oldY;

  for (let i = 0; i < subSteps; i++) {
    currentX += ball.vx * subDt;
    currentY += ball.vy * subDt;

    for (const brick of state.bricks) {
      if (!brick.alive) continue;

      if (collides({ x: currentX, y: currentY, r: ball.r }, brick)) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);

        const dx1 = (currentX + ball.r) - brick.x;
        const dx2 = (brick.x + brick.w) - (currentX - ball.r);
        const dy1 = (currentY + ball.r) - brick.y;
        const dy2 = (brick.y + brick.h) - (currentY - ball.r);

        const min = Math.min(dx1, dx2, dy1, dy2);

        if (min === dx1) {
          ball.vx = -Math.abs(ball.vx);
          currentX = brick.x - ball.r;
        } else if (min === dx2) {
          ball.vx = Math.abs(ball.vx);
          currentX = brick.x + brick.w + ball.r;
        }

        if (min === dy1) {
          ball.vy = -Math.abs(ball.vy);
          currentY = brick.y - ball.r;
        } else if (min === dy2) {
          ball.vy = Math.abs(ball.vy);
          currentY = brick.y + brick.h + ball.r;
        }
        break;
      }
    }
  }

  ball.x = currentX;
  ball.y = currentY;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0;
  }

  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

